export interface DotnetWebRelease {
  asset: { archive: string; sha256: string; url: string };
  draftCommit: string;
  godotCommit: string;
  godotVersion: string;
  tag: string;
  targetFramework: string;
}

export interface DotnetWebToolchain {
  debugTemplatePath: string;
  releaseTemplatePath: string;
  root: string;
}

interface DotnetWebCheckResult {
  message: string;
  toolchain?: DotnetWebToolchain;
  valid: boolean;
}

interface HostOptions {
  arch?: NodeJS.Architecture;
  homeDir?: string;
  platform?: NodeJS.Platform;
  release?: DotnetWebRelease;
  runDotnetWorkloadList?: () => Promise<string>;
}

interface InstallOptions extends HostOptions {
  download?: (options: DownloadFileOptions) => Promise<void>;
  extractArchive?: (archivePath: string, outputDir: string) => Promise<void>;
  godotArgs: string[];
  godotCommand: string;
  output?: DownloadProgressOutput;
  projectDir: string;
  runDotnet?: (command: string, args: string[], cwd: string) => Promise<void>;
  runGodot?: (command: string, args: string[], cwd: string) => Promise<void>;
}

interface PublishOptions {
  configuration: "ExportDebug" | "ExportRelease";
  nugetPackagesDir: string;
  nugetSourceDir: string;
  outputDir: string;
  projectFile: string;
  runDotnet?: (
    command: string,
    args: string[],
    options: { cwd: string; env: NodeJS.ProcessEnv },
  ) => Promise<void>;
}

interface PackOptions {
  godotArgs: string[];
  godotCommand: string;
  outputPath: string;
  preset: string;
  projectDir: string;
  publishDir: string;
  runGodot?: (command: string, args: string[], cwd: string) => Promise<void>;
  userArgs?: string[];
}

interface AssembleOptions {
  assemblerPath: string;
  outputPath: string;
  packPath: string;
  publishDir: string;
  templatePath: string;
}

interface DotnetWebExportOptions {
  arch?: NodeJS.Architecture;
  build: boolean;
  config: ResolvedKirieConfig;
  godotCommand: string;
  homeDir?: string;
  includeWebContent?: boolean;
  outputPath: string;
  platform?: NodeJS.Platform;
  preset: string;
  release: boolean;
  runAssembly?: typeof assembleDotnetWebExport;
  runDotnetWorkloadList?: () => Promise<string>;
  runPack?: typeof exportDotnetWebPack;
  runPublish?: typeof publishDotnetWeb;
  toolchainRelease?: DotnetWebRelease;
  userArgs?: string[];
}

interface Manifest {
  dotnetHost?: string;
  draftCommit?: string;
  files?: Record<string, { sha256?: string; size?: number }>;
  godotCommit?: string;
  godotVersion?: string;
  release?: string;
  schemaVersion?: number;
  targetFramework?: string;
}

const DOTNET_WEB_RELEASE: DotnetWebRelease = {
  asset: {
    archive: "godot-dotnet-web-templates-4.7.2-net10.zip",
    sha256: "affcedcd778a1bdade8d9804496caf99501a7d77a9832d6eb1357f33d734c22f",
    url: "https://github.com/gd-kirie/godot-dotnet-web-templates/releases/download/4.7.2-dotnet10-preview.3/godot-dotnet-web-templates-4.7.2-net10.zip",
  },
  draftCommit: "aa1f5ffe8321bc57155f606197b5aa93dd9e662c",
  godotCommit: "ed1daf0bf001b61586d9930840f2f1394092c079",
  godotVersion: "4.7.2.stable.mono",
  tag: "4.7.2-dotnet10-preview.3",
  targetFramework: "net10.0",
};

const payloadFiles = [
  "Godot.NET.Sdk.4.7.2.nupkg",
  "Godot.SourceGenerators.4.7.2.nupkg",
  "GodotSharp.4.7.2.nupkg",
  "GodotSharpEditor.4.7.2.nupkg",
  "assemble-export.py",
  "web_debug.zip",
  "web_release.zip",
] as const;
const publishManifest = ".dotnet-publish-manifest";
const ignoredPublishSuffixes = [
  ".c",
  ".h",
  ".ts",
  ".js",
  ".js.map",
  ".js.symbols",
  ".rsp",
  ".wasm",
];

export async function checkDotnetWebToolchain(
  options: HostOptions = {},
): Promise<DotnetWebCheckResult> {
  const release = options.release ?? DOTNET_WEB_RELEASE;
  let installDir: string;
  try {
    installDir = resolveDotnetWebInstallDir(options);
  } catch (error) {
    return invalid(error);
  }

  if (!validAsset(release.asset)) {
    return invalid(`${release.tag} has incomplete release asset metadata`);
  }
  if (!existsSync(installDir)) {
    return invalid("not installed");
  }

  try {
    const toolchain = await validateToolchain(installDir, release);
    const workloads = await (options.runDotnetWorkloadList ?? listDotnetWorkloads)();
    if (!/(?:^|\s)wasm-tools(?:\s|$)/m.test(workloads)) {
      return invalid("the .NET wasm-tools workload is not installed");
    }

    return { message: `${release.tag} templates and wasm-tools`, toolchain, valid: true };
  } catch (error) {
    return invalid(error);
  }
}

export async function installDotnetWebToolchain(options: InstallOptions): Promise<void> {
  const release = options.release ?? DOTNET_WEB_RELEASE;
  const installDir = resolveDotnetWebInstallDir(options);
  if (!validAsset(release.asset)) {
    throw new Error(`${release.tag} has incomplete release asset metadata`);
  }

  try {
    await validateToolchain(installDir, release);
  } catch {
    await downloadToolchain(options, installDir, release);
  }

  await (options.runDotnet ?? run)(
    "dotnet",
    ["workload", "install", "wasm-tools"],
    options.projectDir,
  );
  await configureWebPreset(options);
}

export async function tryExportDotnetWeb(options: DotnetWebExportOptions): Promise<boolean> {
  if (!await hasDotnetProject({
    csproj: options.config.godot.csproj,
    projectDir: options.config.godot.project,
  })) {
    return false;
  }

  const checked = await checkDotnetWebToolchain({
    arch: options.arch,
    homeDir: options.homeDir,
    platform: options.platform,
    release: options.toolchainRelease,
    runDotnetWorkloadList: options.runDotnetWorkloadList,
  });
  if (!checked.valid || !checked.toolchain) {
    throw new Error(
      `Kirie Web export found a C# project, but the experimental Godot .NET Web toolchain is ${checked.message}`,
    );
  }

  const temporaryDir = await fs.mkdtemp(path.join(os.tmpdir(), "kirie-dotnet-web-export-"));
  const publishDir = path.join(temporaryDir, "publish");
  try {
    if (options.build) {
      await runBuildWeb({ cwd: options.config.cwd, mode: options.config.mode });
    }
    if (options.includeWebContent !== false) {
      assertViteWebOutput(options.config.web.root);
    }

    await (options.runPublish ?? publishDotnetWeb)({
      configuration: options.release ? "ExportRelease" : "ExportDebug",
      nugetPackagesDir: path.join(checked.toolchain.root, "nuget-packages"),
      nugetSourceDir: checked.toolchain.root,
      outputDir: publishDir,
      projectFile: await resolveDotnetProjectFile(options.config),
    });

    const packPath = path.join(temporaryDir, "project.pck");
    await (options.runPack ?? exportDotnetWebPack)({
      godotArgs: options.config.godot.args,
      godotCommand: options.godotCommand,
      outputPath: packPath,
      preset: options.preset,
      projectDir: options.config.godot.project,
      publishDir,
      userArgs: options.userArgs,
    });
    await (options.runAssembly ?? assembleDotnetWebExport)({
      assemblerPath: path.join(checked.toolchain.root, "assemble-export.py"),
      outputPath: options.outputPath,
      packPath,
      publishDir,
      templatePath: options.release ?
        checked.toolchain.releaseTemplatePath :
        checked.toolchain.debugTemplatePath,
    });
    if (options.includeWebContent !== false) {
      copyViteWebOutput({
        outputDir: path.dirname(options.outputPath),
        webRoot: options.config.web.root,
      });
    }
  } finally {
    await fs.rm(temporaryDir, { force: true, recursive: true });
  }

  return true;
}

export function resolveDotnetWebInstallDir(options: HostOptions = {}): string {
  const platform = options.platform ?? process.platform;
  const arch = options.arch ?? process.arch;
  const supported = (platform === "darwin" && arch === "arm64") ||
    (platform === "linux" && arch === "x64");
  if (!supported) {
    throw new Error(
      `unsupported host ${platform}-${arch}; supported hosts are darwin-arm64 and linux-x64`,
    );
  }

  const home = options.homeDir ?? os.homedir();
  const data = platform === "darwin" ?
      path.join(home, "Library", "Application Support", "Kirie") :
      path.join(home, ".local", "share", "kirie");
  return path.join(data, "dotnet-web", (options.release ?? DOTNET_WEB_RELEASE).tag);
}

export async function publishDotnetWeb(options: PublishOptions): Promise<void> {
  await fs.rm(options.outputDir, { force: true, recursive: true });
  await fs.mkdir(options.outputDir, { recursive: true });
  const restoreDir = await fs.mkdtemp(path.join(os.tmpdir(), "kirie-dotnet-web-restore-"));
  try {
    // PackageDownload installs the local SDK before the application's SDK resolution.
    const project = path.join(restoreDir, "packages.csproj");
    await fs.writeFile(project, `<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup><TargetFramework>net10.0</TargetFramework></PropertyGroup>
  <ItemGroup>
    <PackageDownload Include="Godot.NET.Sdk" Version="[4.7.2]" />
    <PackageDownload Include="Godot.SourceGenerators" Version="[4.7.2]" />
    <PackageDownload Include="GodotSharp" Version="[4.7.2]" />
    <PackageDownload Include="GodotSharpEditor" Version="[4.7.2]" />
  </ItemGroup>
</Project>
`);
    await (options.runDotnet ?? runPublish)("dotnet", [
      "restore",
      project,
      "--source",
      options.nugetSourceDir,
      "--packages",
      options.nugetPackagesDir,
    ], { cwd: restoreDir, env: process.env });
  } finally {
    await fs.rm(restoreDir, { force: true, recursive: true });
  }
  await (options.runDotnet ?? runPublish)(
    "dotnet",
    [
      "publish",
      options.projectFile,
      "-c",
      options.configuration,
      "-r",
      "browser-wasm",
      "--self-contained",
      "true",
      "-p:GodotTargetPlatform=web",
      "-o",
      options.outputDir,
    ],
    {
      cwd: path.dirname(options.projectFile),
      env: { ...process.env, NUGET_PACKAGES: options.nugetPackagesDir },
    },
  );
  await writeDotnetPublishManifest(options.outputDir);
}

export async function exportDotnetWebPack(options: PackOptions): Promise<void> {
  await fs.mkdir(path.dirname(options.outputPath), { recursive: true });
  await (options.runGodot ?? run)(options.godotCommand, [
    ...options.godotArgs,
    "--headless",
    "--path",
    options.projectDir,
    "--export-pack",
    options.preset,
    options.outputPath,
    "--",
    ...(options.userArgs ?? []),
    `--kirie-dotnet-web-publish=${options.publishDir}`,
  ], options.projectDir);

  const output = await fs.stat(options.outputPath);
  if (!output.isFile() || output.size === 0) {
    throw new Error(`Godot did not create the Web pack: ${options.outputPath}`);
  }
}

export async function assembleDotnetWebExport(options: AssembleOptions): Promise<void> {
  await run("python3", [
    options.assemblerPath,
    "--template",
    options.templatePath,
    "--publish",
    options.publishDir,
    "--pack",
    options.packPath,
    "--output",
    options.outputPath,
  ], path.dirname(options.packPath));
}

async function writeDotnetPublishManifest(directory: string): Promise<number> {
  const lines: string[] = [];
  for (const file of await listFiles(directory)) {
    const relative = path.relative(directory, file).split(path.sep).join("/");
    if (
      relative === publishManifest ||
      ignoredPublishSuffixes.some((suffix) => relative.endsWith(suffix))
    ) {
      continue;
    }

    const digest = createHash("sha512").update(await fs.readFile(file)).digest("base64");
    lines.push(`${relative}\t${digest}\n`);
  }
  if (lines.length === 0) {
    throw new Error(`No files remain after filtering .NET Web publish directory: ${directory}`);
  }

  await fs.writeFile(path.join(directory, publishManifest), lines.join(""));
  return lines.length;
}

async function downloadToolchain(
  options: InstallOptions,
  installDir: string,
  release: DotnetWebRelease,
): Promise<DotnetWebToolchain> {
  const temporaryDir = await fs.mkdtemp(path.join(os.tmpdir(), "kirie-dotnet-web-"));
  const archivePath = path.join(temporaryDir, release.asset.archive);
  const extracted = path.join(temporaryDir, "extracted");
  try {
    await (options.download ?? downloadFile)({
      expectedSha256: release.asset.sha256,
      output: options.output ?? process.stderr,
      outputPath: archivePath,
      url: release.asset.url,
    });
    await fs.mkdir(extracted);
    await (options.extractArchive ?? extractZip)(archivePath, extracted);
    await validateToolchain(extracted, release);
    await fs.mkdir(path.dirname(installDir), { recursive: true });
    await fs.rm(installDir, { force: true, recursive: true });
    await fs.cp(extracted, installDir, { recursive: true });
    return await validateToolchain(installDir, release);
  } finally {
    await fs.rm(temporaryDir, { force: true, recursive: true });
  }
}

async function validateToolchain(
  root: string,
  release: DotnetWebRelease,
): Promise<DotnetWebToolchain> {
  const manifest = JSON.parse(
    await fs.readFile(path.join(root, "manifest.json"), "utf8"),
  ) as Manifest;
  if (
    manifest.schemaVersion !== 1 ||
    manifest.dotnetHost !== "standard" ||
    manifest.release !== release.tag ||
    manifest.godotVersion !== release.godotVersion ||
    manifest.godotCommit !== release.godotCommit ||
    manifest.draftCommit !== release.draftCommit ||
    manifest.targetFramework !== release.targetFramework
  ) {
    throw new Error("manifest does not match this Kirie release");
  }

  const files = manifest.files;
  if (!files) {
    throw new Error("manifest has no files");
  }
  for (const [relative, expected] of Object.entries(files)) {
    const file = safePath(root, relative);
    const stat = await fs.stat(file);
    const digest = expected.sha256 && await sha256(file);
    if (!stat.isFile() || stat.size !== expected.size || digest !== expected.sha256) {
      throw new Error(`${relative} is missing or invalid`);
    }
  }
  for (const file of payloadFiles) {
    if (!files[file]?.sha256) {
      throw new Error(`manifest file is missing: ${file}`);
    }
  }

  return {
    debugTemplatePath: path.join(root, "web_debug.zip"),
    releaseTemplatePath: path.join(root, "web_release.zip"),
    root,
  };
}

async function configureWebPreset(options: InstallOptions): Promise<void> {
  const temporaryDir = await fs.mkdtemp(path.join(os.tmpdir(), "kirie-dotnet-web-config-"));
  try {
    const script = path.join(temporaryDir, "configure.gd");
    await fs.writeFile(script, `extends SceneTree

func _init() -> void:
    var preset_path := ProjectSettings.globalize_path("res://export_presets.cfg")
    var config := ConfigFile.new()
    if config.load(preset_path) != OK:
        push_error("Could not load export_presets.cfg.")
        quit(2)
        return

    var index := 0
    while config.has_section("preset.%d" % index):
        var section := "preset.%d" % index
        if config.get_value(section, "platform", "") == "Web":
            var options_section := "%s.options" % section
            config.set_value(options_section, "variant/thread_support", true)
            config.set_value(options_section, "variant/extensions_support", false)
            config.set_value(options_section, "threads/emscripten_pool_size", 24)
            config.set_value(options_section, "threads/godot_pool_size", 4)
            if config.save(preset_path) != OK:
                push_error("Could not save export_presets.cfg.")
                quit(2)
                return
            quit()
            return
        index += 1

    push_error("The project has no Web export preset.")
    quit(2)
`);
    await (options.runGodot ?? run)(options.godotCommand, [
      ...options.godotArgs,
      "--headless",
      "--path",
      options.projectDir,
      "--script",
      script,
    ], options.projectDir);
  } finally {
    await fs.rm(temporaryDir, { force: true, recursive: true });
  }
}

async function resolveDotnetProjectFile(config: ResolvedKirieConfig): Promise<string> {
  if (config.godot.csproj) {
    return config.godot.csproj;
  }

  const projects = (await fs.readdir(config.godot.project, { withFileTypes: true }))
    .filter((entry) => entry.isFile() && path.extname(entry.name).toLowerCase() === ".csproj")
    .map((entry) => path.join(config.godot.project, entry.name));
  if (projects.length === 1) {
    return projects[0]!;
  }
  if (projects.length === 0) {
    throw new Error(`No .csproj found in ${config.godot.project}`);
  }
  throw new Error("Multiple .csproj files found. Set godot.csproj in kirie.config.ts.");
}

function invalid(error: unknown): DotnetWebCheckResult {
  const message = error instanceof Error ? error.message : String(error);
  return { message: `${message} (run: pnpm kirie doctor --fix web)`, valid: false };
}

function validAsset(asset: DotnetWebRelease["asset"]): boolean {
  return Boolean(asset.archive && asset.url && /^[a-f\d]{64}$/i.test(asset.sha256));
}

function safePath(root: string, relative: string): string {
  const resolved = path.resolve(root, relative);
  if (!relative || path.isAbsolute(relative) || path.relative(root, resolved).startsWith("..")) {
    throw new Error(`Invalid toolchain path: ${relative || "empty"}`);
  }
  return resolved;
}

async function listFiles(directory: string): Promise<string[]> {
  const files: string[] = [];
  for (const entry of await fs.readdir(directory, { withFileTypes: true })) {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      files.push(...await listFiles(file));
    } else if (entry.isFile()) {
      files.push(file);
    }
  }
  return files.sort();
}

async function sha256(file: string): Promise<string> {
  return createHash("sha256").update(await fs.readFile(file)).digest("hex");
}

async function listDotnetWorkloads(): Promise<string> {
  return (await execa("dotnet", ["workload", "list"])).stdout;
}

async function run(command: string, args: string[], cwd: string): Promise<void> {
  await execa(command, args, { cwd, stdio: "inherit" });
}

async function runPublish(
  command: string,
  args: string[],
  options: { cwd: string; env: NodeJS.ProcessEnv },
): Promise<void> {
  await execa(command, args, { ...options, stdio: "inherit" });
}
